function Write-Step([string]$Message) {
    Write-Host ""
    Write-Host ("=== " + $Message + " ===") -ForegroundColor Cyan
}

function Get-Sha256Lower([string]$Path) {
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Remove-PathWithRetry {
    param([string]$Path, [int]$Attempts = 8)
    if ([String]::IsNullOrWhiteSpace($Path)) { return }

    for ($i = 1; $i -le $Attempts; $i++) {
        try {
            if (Test-Path -LiteralPath $Path) {
                Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop
            }
            if (-not (Test-Path -LiteralPath $Path)) { return }
        }
        catch {
            if ($i -eq $Attempts) { throw }
        }
        Start-Sleep -Milliseconds (200 * $i)
    }
}

function Stop-TSSEProcesses {
    try {
        Get-Process -Name "TS SE Tool" -ErrorAction SilentlyContinue |
            Stop-Process -Force -ErrorAction SilentlyContinue
    }
    catch { }
    Start-Sleep -Milliseconds 800
}

function Resolve-BaselineSourceZip {
    if (-not [String]::IsNullOrWhiteSpace($BaselineZipPath)) {
        if (-not (Test-Path -LiteralPath $BaselineZipPath -PathType Leaf)) {
            throw "O ZIP H12.1 informado nao existe: $BaselineZipPath"
        }
        return (Resolve-Path -LiteralPath $BaselineZipPath).Path
    }

    if (-not (Test-Path -LiteralPath $DefaultBaselineZip -PathType Leaf)) {
        throw "Nao foi encontrado: $DefaultBaselineZip"
    }
    return (Resolve-Path -LiteralPath $DefaultBaselineZip).Path
}

function Assert-Manifest {
    param([string]$ProjectFolder, [hashtable]$Manifest, [string]$Description)
    $issues = New-Object System.Collections.Generic.List[string]

    foreach ($relative in ($Manifest.Keys | Sort-Object)) {
        $path = Join-Path $ProjectFolder ($relative.Replace('/', '\'))
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            [void]$issues.Add("AUSENTE: $relative")
            continue
        }

        $actual = Get-Sha256Lower $path
        $expected = ([string]$Manifest[$relative]).ToLowerInvariant()
        if ($actual -ne $expected) {
            [void]$issues.Add("HASH: $relative | esperado=$expected | atual=$actual")
        }
    }

    if ($issues.Count -eq 0) { return }

    Write-Host $Description -ForegroundColor Red
    foreach ($issue in $issues) {
        Write-Host " - $issue" -ForegroundColor Yellow
    }
    throw $Description
}

function Get-SourceManifest {
    param([string]$ProjectFolder)

    $manifest = @{}
    Get-ChildItem -LiteralPath $ProjectFolder -Recurse -File | ForEach-Object {
        $relative = $_.FullName.Substring($ProjectFolder.Length)
        $relative = $relative.TrimStart([char[]]@('\', '/')).Replace('\', '/')
        $manifest[$relative] = Get-Sha256Lower $_.FullName
    }
    return $manifest
}

function Assert-OnlyAllowedSourceChanges {
    param(
        [hashtable]$Before,
        [string]$ProjectFolder,
        [string[]]$Allowed
    )

    $after = Get-SourceManifest -ProjectFolder $ProjectFolder
    $allowedSet = @{}
    foreach ($relative in $Allowed) {
        $allowedSet[$relative.Replace('\', '/')] = $true
    }

    $unexpected = New-Object System.Collections.Generic.List[string]
    $changed = New-Object System.Collections.Generic.List[string]
    $allKeys = @($Before.Keys + $after.Keys | Sort-Object -Unique)

    foreach ($relative in $allKeys) {
        $beforeExists = $Before.ContainsKey($relative)
        $afterExists = $after.ContainsKey($relative)
        $isChanged = $beforeExists -ne $afterExists

        if (-not $isChanged -and $beforeExists) {
            $isChanged = ([string]$Before[$relative]) -ne ([string]$after[$relative])
        }
        if (-not $isChanged) {
            continue
        }

        [void]$changed.Add($relative)
        if (-not $allowedSet.ContainsKey($relative)) {
            [void]$unexpected.Add($relative)
        }
    }

    if ($unexpected.Count -gt 0) {
        Write-Host "Arquivos fora do escopo cirurgico foram alterados:" -ForegroundColor Red
        foreach ($relative in $unexpected) {
            Write-Host " - $relative" -ForegroundColor Yellow
        }
        throw "A auditoria de escopo da H21 falhou."
    }

    if ($changed.Count -eq 0) {
        throw "Nenhuma alteracao de fonte foi detectada para a H21."
    }

    Write-Host "Arquivos alterados no escopo H21:" -ForegroundColor DarkGray
    foreach ($relative in $changed) {
        Write-Host " - $relative" -ForegroundColor DarkGray
    }
}

function Patch-CommunitySupportContact {
    param([string]$ProjectFolder)

    $utf8Bom = New-Object System.Text.UTF8Encoding($true)

    $webPath = Join-Path $ProjectFolder "CustomClasses\Utilities\Web_Utilities.cs"
    if (-not (Test-Path -LiteralPath $webPath -PathType Leaf)) {
        throw "Web_Utilities.cs nao foi encontrado para atualizar contato e links."
    }

    $webText = [System.IO.File]::ReadAllText($webPath)
    $replacements = @{
        'internal string linkCheckVersion    = "https://rebrand.ly/TS-SET-CheckVersion";' = 'internal string linkCheckVersion    = "https://raw.githubusercontent.com/fabiomesquita01/ts-se-tool-community/main/latest.txt";'
        'internal string linkDownloadVersion = "https://rebrand.ly/TS-SET-Download";' = 'internal string linkDownloadVersion = "https://github.com/fabiomesquita01/ts-se-tool-community/releases/latest";'
        'internal string linkCheckVersion2 = "https://liptoh.twilightparadox.com/TS-SET-CheckVersion";' = 'internal string linkCheckVersion2 = "https://raw.githubusercontent.com/fabiomesquita01/ts-se-tool-community/main/latest.txt";'
        'internal string linkDownloadVersion2 = "https://liptoh.twilightparadox.com/TS-SET-Download";' = 'internal string linkDownloadVersion2 = "https://github.com/fabiomesquita01/ts-se-tool-community/releases/latest";'
        'internal string linkMailDeveloper = "liptoh.codebase@gmail.com";' = 'internal string linkMailDeveloper = "fabiomalmsteen@gmail.com";'
        'internal string linkGithub = "https://github.com/LIPtoH/TS-SE-Tool";' = 'internal string linkGithub = "https://github.com/fabiomesquita01/ts-se-tool-community";'
        'internal string linkGithubReleases = "https://github.com/LIPtoH/TS-SE-Tool/releases";' = 'internal string linkGithubReleases = "https://github.com/fabiomesquita01/ts-se-tool-community/releases";'
        'internal string linkGithubReleasesLatest = "https://github.com/LIPtoH/TS-SE-Tool/releases/latest";' = 'internal string linkGithubReleasesLatest = "https://github.com/fabiomesquita01/ts-se-tool-community/releases/latest";'
    }
    foreach ($old in $replacements.Keys) {
        if ($webText.IndexOf($old, [StringComparison]::Ordinal) -lt 0) {
            throw "Marcador esperado nao encontrado em Web_Utilities.cs: $old"
        }
        $webText = $webText.Replace($old, $replacements[$old])
    }
    # Web_Utilities.cs is LF in the exact H12.1 archive. ReadAllText/WriteAllText
    # preserves those line endings; the R2/R3/R4 audited hash reflects that exact output.
    [System.IO.File]::WriteAllText($webPath, $webText, $utf8Bom)

    $aboutPath = Join-Path $ProjectFolder "Forms\FormAboutBox.cs"
    if (-not (Test-Path -LiteralPath $aboutPath -PathType Leaf)) {
        throw "FormAboutBox.cs nao foi encontrado para atualizar a continuidade comunitaria."
    }

    # A fonte H12.1 usa LF no ZIP original, enquanto o instalador e executado
    # com CRLF no Windows. A revisao R1 trabalha por linhas e nao depende do
    # tipo de quebra de linha nem do alinhamento exato do bloco localizado.
    $aboutLines = [System.IO.File]::ReadAllLines($aboutPath)
    $atsOld = 'labelATSversion.Text = String.Join(" - ", MainForm.SupportedSavefileVersionETS2.Select(p => p.ToString()).ToArray()) + " (" + MainForm.SupportedGameVersionATS + ")";'
    $atsNew = 'labelATSversion.Text = "Experimental / not validated in RC5.1H21 community release";'
    $atsIndex = -1
    $atsCount = 0
    $formatStart = -1
    $formatArguments = -1
    $referencesAppend = -1

    for ($i = 0; $i -lt $aboutLines.Length; $i++) {
        if ($aboutLines[$i].IndexOf($atsOld, [StringComparison]::Ordinal) -ge 0) {
            $atsIndex = $i
            $atsCount++
        }

        if ($formatStart -lt 0 -and
            $aboutLines[$i].IndexOf(
                'textBoxDescription.Text = string.Format(MainForm.HelpTranslateString(this.Name + textBoxDescription.Name),',
                [StringComparison]::Ordinal) -ge 0) {
            $formatStart = $i
        }
    }

    if ($atsCount -ne 1 -or $atsIndex -lt 0) {
        throw "O rotulo ATS original deveria ocorrer exatamente uma vez em FormAboutBox.cs; ocorrencias: $atsCount."
    }
    if ($formatStart -lt 0) {
        throw "A chamada localizada da autoria original nao foi encontrada em FormAboutBox.cs."
    }

    $searchEnd = [Math]::Min($aboutLines.Length - 1, $formatStart + 4)
    for ($i = $formatStart + 1; $i -le $searchEnd; $i++) {
        if ($aboutLines[$i].IndexOf(
                'Utilities.Web_Utilities.External.linkMailDeveloper',
                [StringComparison]::Ordinal) -ge 0 -and
            $aboutLines[$i].IndexOf(
                'Utilities.Web_Utilities.External.linkGithub',
                [StringComparison]::Ordinal) -ge 0) {
            $formatArguments = $i
            break
        }
    }

    if ($formatArguments -lt 0) {
        throw "Os argumentos da autoria original possuem formato inesperado em FormAboutBox.cs."
    }

    for ($i = $formatArguments + 1; $i -lt $aboutLines.Length; $i++) {
        if ($aboutLines[$i].Trim().Equals(
                'textBoxDescription.Text += referenciesText;',
                [StringComparison]::Ordinal)) {
            $referencesAppend = $i
            break
        }
    }

    if ($referencesAppend -lt 0) {
        throw "A inclusao das referencias de terceiros nao foi encontrada em FormAboutBox.cs."
    }

    for ($i = $formatArguments + 1; $i -lt $referencesAppend; $i++) {
        if ($aboutLines[$i].IndexOf(
                'Community continuation maintained by Fabio',
                [StringComparison]::Ordinal) -ge 0) {
            throw "A continuidade comunitaria ja estava inserida antes da aplicacao H21; fonte inesperada."
        }
    }

    $aboutLines[$atsIndex] = $aboutLines[$atsIndex].Replace($atsOld, $atsNew)

    $formatLine = $aboutLines[$formatArguments]
    $formatLine = $formatLine.Replace(
        'Utilities.Web_Utilities.External.linkMailDeveloper',
        '"liptoh.codebase@gmail.com"')
    $formatLine = $formatLine.Replace(
        'Utilities.Web_Utilities.External.linkGithub',
        '"https://github.com/LIPtoH/TS-SE-Tool"')
    $aboutLines[$formatArguments] = $formatLine

    $newAboutLines = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt $aboutLines.Length; $i++) {
        [void]$newAboutLines.Add($aboutLines[$i])

        if ($i -eq $formatArguments) {
            [void]$newAboutLines.Add('')
            [void]$newAboutLines.Add(
                '            textBoxDescription.Text += Environment.NewLine + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "Community continuation maintained by Fabio" + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "Support: " + Utilities.Web_Utilities.External.linkMailDeveloper + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "Instagram: @fabio.meskita" + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "Instagram link: https://www.instagram.com/fabio.meskita/" + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "Repository: " + Utilities.Web_Utilities.External.linkGithub + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "ETS2 validation: modern save version 97" + Environment.NewLine +')
            [void]$newAboutLines.Add(
                '                                       "ATS status: experimental / not validated" +')
            [void]$newAboutLines.Add(
                '                                       Environment.NewLine + Environment.NewLine;')
        }
    }

    [System.IO.File]::WriteAllLines(
        $aboutPath,
        $newAboutLines.ToArray(),
        $utf8Bom)
}

function Resolve-MSBuild {
    $candidates = New-Object System.Collections.Generic.List[string]
    $vswhere = Join-Path ${env:ProgramFiles(x86)} "Microsoft Visual Studio\Installer\vswhere.exe"
    if (Test-Path -LiteralPath $vswhere -PathType Leaf) {
        try {
            $found = & $vswhere -latest -products * -requires Microsoft.Component.MSBuild -find "MSBuild\**\Bin\MSBuild.exe" | Select-Object -First 1
            if (-not [String]::IsNullOrWhiteSpace($found)) { [void]$candidates.Add($found) }
        }
        catch { }
    }

    foreach ($candidate in @(
        "${env:ProgramFiles(x86)}\Microsoft Visual Studio\2022\BuildTools\MSBuild\Current\Bin\MSBuild.exe",
        "${env:ProgramFiles}\Microsoft Visual Studio\2022\Community\MSBuild\Current\Bin\MSBuild.exe",
        "${env:ProgramFiles}\Microsoft Visual Studio\2022\Professional\MSBuild\Current\Bin\MSBuild.exe",
        "${env:ProgramFiles}\Microsoft Visual Studio\2022\Enterprise\MSBuild\Current\Bin\MSBuild.exe"
    )) {
        if (-not [String]::IsNullOrWhiteSpace($candidate)) { [void]$candidates.Add($candidate) }
    }

    try {
        $command = Get-Command msbuild.exe -ErrorAction SilentlyContinue
        if ($null -ne $command) { [void]$candidates.Add($command.Source) }
    }
    catch { }

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    return ""
}

function Assert-ProjectXml {
    param([string]$ProjectPath)
    [xml]$projectXml = [System.IO.File]::ReadAllText($ProjectPath)
    $ns = New-Object System.Xml.XmlNamespaceManager($projectXml.NameTable)
    $ns.AddNamespace("msb", "http://schemas.microsoft.com/developer/msbuild/2003")

    foreach ($include in @(
        "ModernMarketsH13R.cs",
        "ModernTrailerSwitchH14.cs",
        "ModernSteeringWheelH15.cs",
        "ModernAccessoryPackageH19.cs",
        "Forms\MainTabs\FormMethodsTruckTab.cs",
        "ModernVehicleCompatibility.cs",
        "Forms\MainTabs\FormMethodsFreightMarketTab.cs.cs",
        "Forms\MainTabs\FormMethodsCargoMarkerTab.cs.cs"
    )) {
        $nodes = @($projectXml.SelectNodes("//msb:Compile[@Include='$include']", $ns))
        if ($nodes.Count -ne 1) {
            throw "O projeto deve incluir exatamente uma vez: $include. Encontrado: $($nodes.Count)"
        }
    }
}


Write-Step "Validando as bases homologadas"
Write-Host "Instalador: RC5.1H21-FINAL-R4" -ForegroundColor DarkGray
Stop-TSSEProcesses

$sourceZip = Resolve-BaselineSourceZip
if ((Get-Sha256Lower $sourceZip) -ne $BaselineZipSha256) {
    throw "O ZIP da fonte H12.1 nao corresponde ao arquivo exato analisado."
}

$baseExe = Join-Path $BaseOutputFolder "TS SE Tool.exe"
if (-not (Test-Path -LiteralPath $baseExe -PathType Leaf)) {
    throw "A pasta homologada H18.1 nao foi encontrada: $BaseOutputFolder"
}
$baseVersion = (Get-Item -LiteralPath $baseExe).VersionInfo.FileVersion
if ($baseVersion -notlike "0.3.11.41*") {
    throw "O executavel-base deveria ser 0.3.11.41, mas foi encontrado: $baseVersion"
}

$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("TSSE_H21_BUILD_" + [Guid]::NewGuid().ToString("N"))
$sourceRoot = Join-Path $tempRoot "source"
$projectFolder = Join-Path $sourceRoot "TS SE Tool"
$projectPath = Join-Path $projectFolder "TS SE Tool.csproj"
$solutionPath = Join-Path $sourceRoot "TS SE Tool.sln"
$payloadZip = Join-Path $tempRoot "payload.zip"
$payloadRoot = Join-Path $tempRoot "payload"
$staging = Join-Path $DownloadsPath ("TS.SE.Tool.0.3.11.47-RC5.1H21-FINAL.staging-" + [Guid]::NewGuid().ToString("N"))

try {
    Write-Step "Extraindo e validando a fonte H12.1 em area temporaria"
    New-Item -ItemType Directory -Path $sourceRoot -Force | Out-Null
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($sourceZip, $sourceRoot)

    foreach ($required in @($projectFolder, $projectPath, $solutionPath)) {
        if (-not (Test-Path -LiteralPath $required)) {
            throw "Estrutura ausente no ZIP H12.1: $required"
        }
    }
    Assert-Manifest -ProjectFolder $projectFolder -Manifest $BaselineHashes -Description "A fonte temporaria nao corresponde integralmente a H12.1 homologada."
    $sourceManifestBefore = Get-SourceManifest -ProjectFolder $projectFolder

    Write-Step "Aplicando a linha homologada ate H20 e o fechamento H21 na copia temporaria"
    $payloadBytes = [Convert]::FromBase64String(($PayloadBase64 -replace '\s', ''))
    [System.IO.File]::WriteAllBytes($payloadZip, $payloadBytes)
    if ((Get-Sha256Lower $payloadZip) -ne $PayloadSha256) {
        throw "O payload interno H21 falhou na verificacao SHA-256."
    }
    [System.IO.Compression.ZipFile]::ExtractToDirectory($payloadZip, $payloadRoot)
    $payloadProject = Join-Path $payloadRoot "TS SE Tool"

    foreach ($relative in @(
        "ModernMarketsH13R.cs",
        "ModernGaragesH10.cs",
        "ModernVehicleCompatibility.cs",
        "ModernTrailerSwitchH14.cs",
        "ModernSteeringWheelH15.cs",
        "ModernAccessoryPackageH19.cs",
        "ModernFeatureCompletionH20.cs",
        "Forms/MainTabs/FormMethodsTruckTab.cs",
        "CustomClasses/Save/Items/Economy.cs",
        "CustomClasses/Utilities/IO_Utilities.cs",
        "FormMethods.cs",
        "MethodsReadWrite.cs",
        "TS SE Tool.csproj",
        "Properties/AssemblyInfo.cs"
    )) {
        $source = Join-Path $payloadProject ($relative.Replace('/', '\'))
        $destination = Join-Path $projectFolder ($relative.Replace('/', '\'))
        if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
            throw "Arquivo ausente no payload auditado: $relative"
        }
        $parent = Split-Path -Parent $destination
        if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
            New-Item -ItemType Directory -Path $parent -Force | Out-Null
        }
        Copy-Item -LiteralPath $source -Destination $destination -Force
    }

    Patch-CommunitySupportContact -ProjectFolder $projectFolder
    Assert-OnlyAllowedSourceChanges `
        -Before $sourceManifestBefore `
        -ProjectFolder $projectFolder `
        -Allowed $AllowedSourceChanges

    Assert-Manifest -ProjectFolder $projectFolder -Manifest $TargetHashes -Description "A copia temporaria nao corresponde ao alvo H21 auditado."
    Assert-ProjectXml -ProjectPath $projectPath

    $webText = [System.IO.File]::ReadAllText(
        (Join-Path $projectFolder "CustomClasses\Utilities\Web_Utilities.cs"))
    foreach ($webMarker in @(
        'internal string linkMailDeveloper = "fabiomalmsteen@gmail.com";',
        'internal string linkGithub = "https://github.com/fabiomesquita01/ts-se-tool-community";',
        'internal string linkGithubReleasesLatest = "https://github.com/fabiomesquita01/ts-se-tool-community/releases/latest";',
        'https://raw.githubusercontent.com/fabiomesquita01/ts-se-tool-community/main/latest.txt'
    )) {
        if ($webText.IndexOf($webMarker, [StringComparison]::Ordinal) -lt 0) {
            throw "Marcador comunitario ausente em Web_Utilities.cs: $webMarker"
        }
    }
    if ($webText.IndexOf(
            'internal string linkMailDeveloper = "liptoh.codebase@gmail.com";',
            [StringComparison]::Ordinal) -ge 0) {
        throw "O contato operacional antigo ainda esta ativo em Web_Utilities.cs."
    }

    $aboutText = [System.IO.File]::ReadAllText(
        (Join-Path $projectFolder "Forms\FormAboutBox.cs"))
