    $assemblyText = [System.IO.File]::ReadAllText((Join-Path $projectFolder "Properties\AssemblyInfo.cs"))
    if ($assemblyText.IndexOf('AssemblyFileVersion("0.3.11.47")', [StringComparison]::Ordinal) -lt 0) {
        throw "A versao 0.3.11.47 nao foi aplicada ao projeto."
    }

    Write-Step "Compilando RC5.1H21-FINAL"
    $msbuild = Resolve-MSBuild
    if ([String]::IsNullOrWhiteSpace($msbuild)) {
        throw "MSBuild nao encontrado."
    }
    & $msbuild $solutionPath /t:Rebuild /p:Configuration=Release /p:Platform="Any CPU" /m
    if ($LASTEXITCODE -ne 0) {
        throw "A compilacao RC5.1H21 falhou. Nenhuma fonte persistente foi alterada."
    }

    $builtExe = Join-Path $projectFolder "bin\Release\TS SE Tool.exe"
    if (-not (Test-Path -LiteralPath $builtExe -PathType Leaf)) {
        throw "Executavel compilado nao encontrado: $builtExe"
    }
    $builtVersion = (Get-Item -LiteralPath $builtExe).VersionInfo.FileVersion
    if ($builtVersion -notlike "0.3.11.47*") {
        throw "Versao inesperada no executavel H21: $builtVersion"
    }

    Write-Step "Montando a nova pasta sem alterar a base homologada"
    Remove-PathWithRetry $staging
    New-Item -ItemType Directory -Path $staging -Force | Out-Null
    Get-ChildItem -LiteralPath $BaseOutputFolder -Force |
        Copy-Item -Destination $staging -Recurse -Force
    Copy-Item -LiteralPath $builtExe -Destination (Join-Path $staging "TS SE Tool.exe") -Force

    foreach ($logName in @("log.log", "errorlog.log", "compatibility.log")) {
        $logPath = Join-Path $staging $logName
        if (Test-Path -LiteralPath $logPath -PathType Leaf) {
            Clear-Content -LiteralPath $logPath
        }
    }

    Get-ChildItem -LiteralPath $staging -Filter "README_RC5*.txt" -File -ErrorAction SilentlyContinue |
        Remove-Item -Force -ErrorAction SilentlyContinue

    $readme = @'
TS SE Tool 0.3.11.47 RC5.1H21 FINAL

STATUS
- Release comunitaria final da sequencia RC5.1.
- Suporte publico: Euro Truck Simulator 2.
- Validacao concluida com save moderno de versao 97.
- American Truck Simulator: experimental e NAO validado; nao e requisito para usar a release ETS2.

SEGURANCA
- Use sempre uma copia do save e mantenha o jogo fechado durante a edicao.
- O programa cria backup timestamped antes da escrita.
- Operacoes sem writer moderno comprovado permanecem bloqueadas.
- Nao ha salvamento automatico ao preparar alteracoes.

RECURSOS PRINCIPAIS
- Perfil, empresa, saldo, experiencia, habilidades e cores.
- Caminhoes e reboques: manutencao, combustivel, placa, odometro e lotes.
- Garagens, sede e cidades visitadas.
- Freight Market e Cargo Market com validacao semantica.
- Ferramentas seguras de comboio para posicao e rota.
- Troca controlada de caminhoes/reboques em topologias homologadas.
- Editor seguro de pecas com alternativas verificadas.
- Edicao cirurgica das seis habilidades dos motoristas IA.
- Central de recursos e indice somente leitura de pasta def extraida.

LIMITES INTENCIONAIS
- Contratar/demitir motoristas nao esta disponivel.
- Colar caminhao/reboque completo e editor bruto permanecem indisponiveis.
- Catalogo nativo universal de DLCs/mods nao esta incluido.
- ATS nao foi validado nesta release.

LOGS
- log.log: operacoes e validacoes normais.
- errorlog.log: somente erros reais e excecoes.
- compatibility.log: campos/blocos novos ainda preservados como dados nao identificados.

PROJETO E SUPORTE
- Repositorio: https://github.com/fabiomesquita01/ts-se-tool-community
- Issues: https://github.com/fabiomesquita01/ts-se-tool-community/issues
- Suporte: fabiomalmsteen@gmail.com
- Instagram: @fabio.meskita — https://www.instagram.com/fabio.meskita/
- Projeto original: LIPtoH — https://github.com/LIPtoH/TS-SE-Tool
- Licenca: Apache License 2.0.
'@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "README_RC5.1H21_FINAL.txt"),
        $readme,
        [System.Text.UTF8Encoding]::new($true))

    $tests = @'
TESTES FINAIS RC5.1H21

1. Confirmar build com 0 erros e apenas os tres warnings historicos.
2. Abrir TS SE Tool.exe e confirmar versao 0.3.11.47.
3. Carregar uma copia do save ETS2 moderno.
4. Confirmar no log: RC5.1H21 final release initialized.
5. Abrir Program > Central de recursos — versao final.
6. Confirmar ETS2 como suportado/testado e ATS como experimental/nao validado.
7. Confirmar que errorlog.log permanece vazio durante carregamento normal.
8. Confirmar que compatibility.log recebe diagnosticos de campos/blocos desconhecidos.
9. Editar uma unica habilidade de um motorista IA, salvar uma vez e recarregar.
10. Preparar uma unica troca de peca verificada, salvar uma vez e recarregar.
11. Conferir diff cirurgico: somente os campos selecionados podem mudar.
12. Abrir o save no ETS2 e validar motorista, caminhao, acessorios, radar e garagens.
13. Abrir a tela Sobre e confirmar email, Instagram @fabio.meskita e repositorio comunitario.
14. Na Central de recursos, clicar em Abrir Instagram e confirmar o perfil correto.
15. Confirmar que contratar/demitir, editor bruto e colagem completa continuam bloqueados.
16. Verificar a criacao do ZIP final e do SHA256SUMS.txt.

ATS NAO FAZ PARTE DO ACEITE DESTA RELEASE.
'@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "TESTES_FINAIS_RC5.1H21.txt"),
        $tests,
        [System.Text.UTF8Encoding]::new($true))

    $limitations = @'
MATRIZ DE SUPORTE RC5.1H21 FINAL

EURO TRUCK SIMULATOR 2
- SUPORTADO nesta release comunitaria.
- Faixa declarada pelo editor: saves 61 a 97.
- Validacao comunitaria principal: save moderno 97.

AMERICAN TRUCK SIMULATOR
- EXPERIMENTAL / NAO VALIDADO.
- A ausencia do ATS no ambiente de testes nao bloqueia a release ETS2.
- Relatos ATS devem usar o template especifico no GitHub e incluir backup, versao do jogo, save version, log.log, errorlog.log e compatibility.log.

CANAIS COMUNITARIOS
- Email: fabiomalmsteen@gmail.com
- Instagram: @fabio.meskita
- Link: https://www.instagram.com/fabio.meskita/
- GitHub: https://github.com/fabiomesquita01/ts-se-tool-community

RECURSOS INDISPONIVEIS POR SEGURANCA
- contratar/demitir motorista;
- editor bruto com insercao, exclusao ou reordenacao;
- colar grafos completos de veiculo/reboque;
- caminhos manuais de pecas no modo gamer;
- suporte universal a mods e DLCs sem dependencias verificadas.
'@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "LIMITACOES_E_SUPORTE_RC5.1H21.txt"),
        $limitations,
        [System.Text.UTF8Encoding]::new($true))

    $releaseNotes = @'
# TS SE Tool Community 0.3.11.47 — RC5.1H21 Final

Final community release focused on safe Euro Truck Simulator 2 save editing.

## Highlights
- Safe modern writer retained across profile, company, fleet, garages, markets, convoy, accessories and AI-driver skills.
- Compatibility diagnostics moved from `errorlog.log` to `compatibility.log`.
- Community GitHub, releases and update links configured.
- Community contact displayed in-app: fabiomalmsteen@gmail.com and Instagram @fabio.meskita.
- Explicit support matrix: ETS2 supported/tested; ATS experimental and unvalidated.
- Unsafe legacy graph mutations remain disabled by design.

## Important
Back up the profile and test on a copied save. This project is not affiliated with or endorsed by SCS Software.
'@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "RELEASE_NOTES_v0.3.11.47.md"),
        $releaseNotes,
        [System.Text.UTF8Encoding]::new($true))

    [System.IO.File]::WriteAllText(
        (Join-Path $staging "SOURCE_CODE_URL.txt"),
        "https://github.com/fabiomesquita01/ts-se-tool-community" + [Environment]::NewLine,
        [System.Text.UTF8Encoding]::new($true))

    Copy-Item -LiteralPath (Join-Path $sourceRoot "LICENSE") -Destination (Join-Path $staging "LICENSE") -Force

    $thirdParty = @'
THIRD-PARTY NOTICES

This distribution preserves the original TS SE Tool notices and source references.
Third-party components include SII Decrypt, PsColorPicker/OpenPainter, SharpZipLib,
SQL Server Compact/SqlCeBulkCopy, DDSImageParser, TGASharpLib and FlexibleMessageBox.
Refer to the source repository, package license files and the About screen for the
canonical copyright and license notices of each component.

Original project: https://github.com/LIPtoH/TS-SE-Tool
Community repository: https://github.com/fabiomesquita01/ts-se-tool-community
'@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "THIRD_PARTY_NOTICES.txt"),
        $thirdParty,
        [System.Text.UTF8Encoding]::new($true))

    $installerHash = "indisponivel"
    try {
        if (-not [String]::IsNullOrWhiteSpace($MyInvocation.MyCommand.Path) -and
            (Test-Path -LiteralPath $MyInvocation.MyCommand.Path -PathType Leaf)) {
            $installerHash = Get-Sha256Lower $MyInvocation.MyCommand.Path
        }
    }
    catch { }

    $manifestText = @"
TS SE Tool 0.3.11.47 RC5.1H21 FINAL — manifesto de build
Fonte H12.1 SHA-256: $BaselineZipSha256
Payload interno SHA-256: $PayloadSha256
Instalador SHA-256: $installerHash
Executavel base: $baseVersion
Executavel base SHA-256: $(Get-Sha256Lower $baseExe)
Executavel gerado: $builtVersion
Executavel gerado SHA-256: $(Get-Sha256Lower $builtExe)
Base homologada copiada de: $BaseOutputFolder
Repositorio comunitario: https://github.com/fabiomesquita01/ts-se-tool-community
Instagram comunitario: https://www.instagram.com/fabio.meskita/
ATS validado: nao
Data local do build: $(Get-Date -Format "yyyy-MM-dd HH:mm:ss zzz")
"@
    [System.IO.File]::WriteAllText(
        (Join-Path $staging "MANIFEST_RC5.1H21_FINAL.txt"),
        $manifestText,
        [System.Text.UTF8Encoding]::new($true))

    foreach ($relative in @(
        "TS SE Tool.exe",
        "TS SE Tool.exe.config",
        "libs\SII_Decrypt.dll",
        "libs\ErikEJ.SqlCe40.dll",
        "libs\ICSharpCode.SharpZipLib.dll",
        "libs\OpenPainter.ColorPicker.dll",
        "libs\x86\sqlceca40.dll",
        "libs\amd64\sqlceca40.dll"
    )) {
        if (-not (Test-Path -LiteralPath (Join-Path $staging $relative) -PathType Leaf)) {
            throw "Arquivo essencial ausente no pacote final: $relative"
        }
    }

    $stagedVersion = (Get-Item -LiteralPath (Join-Path $staging "TS SE Tool.exe")).VersionInfo.FileVersion
    if ($stagedVersion -notlike "0.3.11.47*") {
        throw "O staging nao recebeu o executavel 0.3.11.47."
    }

    Remove-PathWithRetry $OutputFolder
    Move-Item -LiteralPath $staging -Destination $OutputFolder -Force

    if (Test-Path -LiteralPath $CurrentOutputZip -PathType Leaf) {
        Remove-Item -LiteralPath $CurrentOutputZip -Force
    }

    $checksumLines = New-Object System.Collections.Generic.List[string]
    Get-ChildItem -LiteralPath $OutputFolder -Recurse -File |
        Sort-Object FullName |
        ForEach-Object {
            $relativeHashPath = $_.FullName.Substring($OutputFolder.Length).TrimStart('\')
            [void]$checksumLines.Add((Get-Sha256Lower $_.FullName) + "  " + $relativeHashPath)
        }
    [System.IO.File]::WriteAllLines(
        (Join-Path $OutputFolder "SHA256SUMS.txt"),
        $checksumLines.ToArray(),
        [System.Text.UTF8Encoding]::new($false))

    [System.IO.Compression.ZipFile]::CreateFromDirectory(
        $OutputFolder,
        $CurrentOutputZip,
        [System.IO.Compression.CompressionLevel]::Optimal,
        $false)

    Write-Host ""
    Write-Host "RC5.1H21 FINAL CONCLUIDA" -ForegroundColor Green
    Write-Host "Pasta criada: $OutputFolder"
    Write-Host "ZIP final: $CurrentOutputZip"
    Write-Host "Base H18.1 preservada: $BaseOutputFolder" -ForegroundColor DarkGray
    Write-Host "Teste somente em copia do save e siga o TESTES_FINAIS_RC5.1H21.txt." -ForegroundColor Yellow
}
finally {
    try {
        if (Test-Path -LiteralPath $staging) {
            Stop-TSSEProcesses
            Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
    catch {
        Write-Warning "Nao foi possivel remover o staging temporario: $staging"
    }

    try {
        if (Test-Path -LiteralPath $tempRoot) {
            Stop-TSSEProcesses
            for ($cleanupAttempt = 1; $cleanupAttempt -le 10; $cleanupAttempt++) {
                Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
                if (-not (Test-Path -LiteralPath $tempRoot)) { break }
                [GC]::Collect()
                [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds (250 * $cleanupAttempt)
            }
        }
    }
    catch {
        Write-Warning "Nao foi possivel remover a fonte temporaria: $tempRoot"
    }
}
